def data_of(page: str) -> dict:
    start = page.index('id="s2s-data">') + len('id="s2s-data">')
    return json.loads(page[start:page.index("</script>", start)])


def test_the_page_holds_repo_and_github_data_and_hostile_text_stays_text(root, fake):
    hub = tickets.Hub(REPO)
    n = fake.make("Card payments", "", ["ticket", "role:engineer", "claimed"])
    hub.record(n, "engineer", "claimed", EVIL)
    wait = fake.make("[approval] Deploy payments", "**Requested by:** role:engineer\n**Scope:** this action only",
                     [approval.LABEL, "gate:deploy"])
    fake.comments[wait].append({"user": {"login": "someone-else"}, "body": "/approve"})
    done = fake.make("[approval] Email users", "", [approval.LABEL, "gate:deploy"], state="closed")
    fake.comments[done].append({"user": {"login": "acme"}, "body": "/approve"})
    log = fake.make("Cost log 2026-11", "", [heartbeat.COST_LOG])
    fake.comments[log].append({"body": heartbeat.cost_entry("engineer", 8.5, "2026-11", "measured", n, "run"),
                               "created_at": "2026-11-22T10:00:00Z"})

    page = bd.page(bd.build(root, now=NOW))
    assert page.count("</script>") == 2, "no text from the repo or GitHub can close the data element"
    assert "<img src=x" not in page and " " not in page
    assert bd.MARKER in page and "<title>Example Startup dashboard</title>" in page
    d = data_of(page)
    assert d["github"]["ok"] and d["month"] == "2026-11"
    assert [a["why"].replace("\n", "\u2028") for a in d["github"]["activity"]] == [EVIL]
    states = {a["number"]: (a["state"], a["open"]) for a in d["github"]["approvals"]}
    assert states == {wait: ("waiting", True), done: ("approved", False)}, "only the founder's /approve counts"
    eng = next(r for r in d["github"]["costs"]["roles"] if r["role"] == "engineer")
    assert {k: eng[k] for k in ("role", "used", "cap", "base")} == {"role": "engineer", "used": 8.5, "cap": 10.0, "base": 10.0}
    assert eng["daily"] == [{"date": "2026-11-22", "usd": 8.5}] and eng["stats"]["runs"] == 1
    assert [p["number"] for p in d["github"]["merged"]] == [7]
    assert d["github"]["tickets"][0]["claimed"]
    paths = [doc["path"] for doc in d["repo"]["documents"]]
    assert paths == ["founder/business-context.md", "founder/sources/interviews.md"]
    assert [m["path"] for m in d["repo"]["memos"]] == ["founder/board/pricing.md"]
    assert [x["status"] for x in d["repo"]["decisions"]] == ["Proposed", "Approved"]
    assert d["repo"]["trace"]["chain"][2]["done"] == 1 and d["repo"]["epics"][0]["code"] == "INV"
    assert d["repo"]["heartbeats"]["engineer"]["enabled"] is True


def test_github_down_still_builds_the_repo_tabs(root, fake, monkeypatch, tmp_path, capsys):
    def down(*a, **k):
        raise FileNotFoundError("gh")
    monkeypatch.setattr(tickets, "gh", down)
    out = tmp_path / "site"
    assert bd.main(["build", "--root", str(root), "--out", str(out)]) == 0
    assert "GitHub data: missing" in capsys.readouterr().out
    d = data_of((out / "index.html").read_text(encoding="utf-8"))
    assert d["github"] == {"ok": False, "repo": REPO, "why": "GitHub unavailable or unexpected reply (FileNotFoundError)"}
    assert d["repo"]["roadmap"]["slices"][0]["id"] == "S1"
    assert (out / "robots.txt").read_text(encoding="utf-8").endswith("Disallow: /\n")


