# --- hosting ------------------------------------------------------------------------------------------------

def host_settings(root: Path, host: str = "pm.example.com", project: str = "example-pm") -> None:
    (root / "founder/dashboard.json").write_text(json.dumps({"host": host, "cloudflare_pages_project": project}),
                                                encoding="utf-8")


def app(*domains: str, policies: list | None = None, **extra) -> dict:
    return {"name": "dashboard", "type": "self_hosted", "domain": domains[0], "self_hosted_domains": list(domains),
            "policies": [{"decision": "allow", "include": [{"email": {"email": "founder@example.com"}}]}]
            if policies is None else policies, **extra}


def guard(root: Path, monkeypatch, tmp_path: Path, apps: list | None, secrets: bool = True) -> tuple[int, str]:
    if secrets:
        monkeypatch.setenv("CLOUDFLARE_API_TOKEN", "t")
        monkeypatch.setenv("CLOUDFLARE_ACCOUNT_ID", ACCOUNT)
    else:
        monkeypatch.delenv("CLOUDFLARE_API_TOKEN", raising=False)
        monkeypatch.delenv("CLOUDFLARE_ACCOUNT_ID", raising=False)

    def http(url, headers=None):
        assert url.startswith(f"{bd.CF_API}/accounts/{ACCOUNT}/access/apps") and headers["Authorization"] == "Bearer t"
        if apps is None:
            return 403, {}, json.dumps({"success": False})
        return 200, {}, json.dumps({"success": True, "result": apps, "result_info": {"total_pages": 1}})
    monkeypatch.setattr(bd, "http", http)
    out = tmp_path / "gh-out"
    out.write_text("", encoding="utf-8")
    code = bd.main(["guard", "--root", str(root), "--github-output", str(out)])
    return code, out.read_text(encoding="utf-8")


def test_no_hosting_or_no_secrets_builds_only(root, monkeypatch, tmp_path):
    assert guard(root, monkeypatch, tmp_path, []) == (0, "deploy=no\nproject=\n")
    host_settings(root)
    assert guard(root, monkeypatch, tmp_path, [], secrets=False) == (0, "deploy=no\nproject=\n")
    host_settings(root, host="pm.example.com; rm -rf /")
    assert guard(root, monkeypatch, tmp_path, [])[0] == 1


@pytest.mark.parametrize("apps", [
    [],                                                                     # no login at all
    [app("pm.example.com")],                                                # pages.dev left open
    [app("pm.example.com/admin", "example-pm.pages.dev")],                  # only part of the site
    [app("*.example-pm.pages.dev", "pm.example.com")],                      # previews only, not production
    [app("pm.example.com", "example-pm.pages.dev", policies=[])],
    [app("pm.example.com", "example-pm.pages.dev", policies=[{"decision": "allow", "include": [{"everyone": {}}]}])],
    [app("pm.example.com", "example-pm.pages.dev", policies=[{"decision": "bypass", "include": [{"everyone": {}}]}])],
    None,                                                                   # the API refuses
])
def test_guard_fails_closed_without_a_real_login(root, monkeypatch, tmp_path, apps):
    host_settings(root)
    code, out = guard(root, monkeypatch, tmp_path, apps)
    assert (code, out) == (1, "deploy=no\nproject=\n")


def test_guard_allows_a_deploy_behind_access(root, monkeypatch, tmp_path):
    host_settings(root)
    apps = [app("pm.example.com"), app("example-pm.pages.dev"), {"type": "ssh", "domain": "*"}]
    assert guard(root, monkeypatch, tmp_path, apps) == (0, "deploy=yes\nproject=example-pm\n")
    one = [{"type": "self_hosted", "name": "d", "destinations": [{"type": "public", "uri": "pm.example.com/*"},
                                                                  {"type": "public", "uri": "example-pm.pages.dev"}],
            "policies": [{"decision": "allow", "include": [{"github-organization": {"name": "acme"}}]}]}]
    assert guard(root, monkeypatch, tmp_path, one)[1] == "deploy=yes\nproject=example-pm\n"


def test_verify_fails_when_anyone_can_read_it(root, monkeypatch, capsys):
    host_settings(root)
    replies = {"https://pm.example.com/": (302, {"Location": "https://acme.cloudflareaccess.com/"}, ""),
               "https://example-pm.pages.dev/": (200, {}, f"<meta {bd.MARKER} content=\"1\">")}
    monkeypatch.setattr(bd, "http", lambda url, headers=None: replies[url])
    assert bd.main(["verify", "--root", str(root)]) == 1
    assert "EXPOSED: https://example-pm.pages.dev/" in capsys.readouterr().out
    replies["https://example-pm.pages.dev/"] = (403, {}, "Forbidden")
    assert bd.main(["verify", "--root", str(root)]) == 0


